export interface ConditionMatch {
  matched: string[];
  mismatched: string[];
  not_in_source: string[];
}

/**
 * 가격 줄. 후보 범위의 두 값은 서로 다른 후보 상품의 확인된 가격이며 보간 값이 아니다
 */
export interface PriceLine {
  basis?: PriceBasis;
  /**
   * 만원, 보기용. 후보 범위면 두 값(최저·최고)
   */
  man?: number[];
  candidates?: number;
  as_of?: string;
  unpriced?: number;
  price_unavailable_reason?: PriceUnavailableReason;
  condition_match?: ConditionMatch;
}

/**
 * 해소되지 않은 항목. 행의 hold_count·data_missing_count는 이 목록에서 센다
 */
export interface UnresolvedItem {
  display_status: DisplayStatus;
  line: string;
  refs: string[];
}

/**
 * 보장 묶음 한 행
 */
export interface PlanGroup {
  id: string;
  title: string;
  subtitle?: string;
  plan_action: PlanAction;
  row_label: RowLabel;
  price_line: PriceLine;
  coverage_occurrence_ids: string[];
  premium_observation_ids: string[];
  unresolved_items: UnresolvedItem[];
  need?: NeedSummary;
}

/**
 * 필요 담보 행에 붙는 필요성 요약 (02 §2.4)
 */
export interface NeedSummary {
  /**
   * keep, no_add, hold, review_add
   */
  verdict: NeedVerdict;
  reasons: NeedReason[];
}

/**
 * 차이 항목 하나. 줄어드는 것도 항상 계산한다(I9)
 */
export interface DiffItem {
  diff_type: DiffType;
  amounts: Amount[];
}

/**
 * 차이 묶음
 */
export interface PlanDiffGroup {
  group: DiffGroup;
  items: DiffItem[];
}

/**
 * 두 안의 차이
 */
export interface PlanDiff {
  groups: PlanDiffGroup[];
}

/**
 * 내 설계 탭 뷰모델 (화면 설계서 §11, 02_구현계약 §2.4). 화면은 이 구조만 받아 그린다
 */
export interface PlanView {
  /**
   * 뷰 이름
   */
  view: string;
  plan_id: string;
  input_hash: string;
  release_id: string;
  data_as_of: string;
  budget: Budget;
  /**
   * current, proposal (화면 설계서 §4.3). 어휘 축 승격 대기
   */
  tab: string;
  comparison_basis_id: string;
  price_caption: PriceCaption;
  groups: PlanGroup[];
  data_missing_count: number;
  unpriced_count: number;
  diff_available: boolean;
  /**
   * 합성 데이터로 만든 화면이면 true
   */
  synthetic: boolean;
  diff?: PlanDiff;
  result_state: ResultState;
}

/**
 * 가격 관측치. 원시 관측은 공백이 있어도 보존하고 비교 자격은 따로 둔다 (02_구현계약 §1.2, PREMIUM_DATA_CONTRACT)
 */
export interface PremiumObservation {
  id: string;
  /**
   * 근거 1개 이상
   */
  evidence: EvidenceLink[];
  /**
   * 원문 금액(정수 원). 공백이 있어도 보존한다
   */
  raw_amount: number;
  price_basis: PriceBasis;
  observed_at: string;
  source_published_at?: string;
  /**
   * 소스가 밝힌 기준일
   */
  source_as_of?: string;
  /**
   * 월납·연납 등. 연납÷12를 월납으로 쓰지 않는다. 어휘 축 승격 대기
   */
  payment_cycle?: string;
  /**
   * 가격 조건(차원 -> 값). 조건 차원은 라벨 사전이 정의하는 열린 집합
   */
  conditions?: Record<string, string>;
  /**
   * 조건마다 어디서 왔는지(차원 -> 출처)
   */
  condition_sources?: Record<string, string>;
  /**
   * none, requires_main, source_bundle, requires_base_contract (PREMIUM_DATA_CONTRACT). 어휘 축 승격 대기
   */
  package_binding?: string;
  /**
   * 원문에 없는 조건 차원
   */
  missing_dimensions: string[];
  comparison_basis_id?: string;
  /**
   * 조건·구성·기준일이 모두 있고 accepted일 때만 true (K13)
   */
  comparison_eligible: boolean;
  value_state: ValueState;
  review_status: ReviewStatus;
  review_decision_id?: string;
  /**
   * pipeline, fixture
   */
  origin: AssertionOrigin;
}

/**
 * 릴리스가 읽는 구성원 ID 목록(정렬). 이 목록뿐이다 (02 §1.3)
 */
export interface ReleaseMembers {
  raw_assets: string[];
  segments: string[];
  terms_editions: string[];
  terms_lineages: string[];
  clauses: string[];
  nodes: string[];
  assertions: string[];
  conflicts: string[];
  gaps: string[];
  premium_observations: string[];
  /**
   * 판단 기준 릴리스는 별도 ID로 고정하고 참조만 한다
   */
  criteria_release_ref?: string;
}

/**
 * 사용한 모델. 식별자 원문은 싣지 않고 해시만 싣는다
 */
export interface ModelVersion {
  /**
   * 제공자 계열 라벨
   */
  provider_family_label: string;
  model_ref_hash: string;
  prompt_version: string;
}

/**
 * 릴리스 manifest. 불변이며 롤백은 manifest 교체다 (02_구현계약 §1.3)
 */
export interface ReleaseManifest {
  release_id: string;
  created_at: string;
  frozen_at: string;
  members: ReleaseMembers;
  /**
   * 규칙 파일 경로 -> 바이트 해시
   */
  rule_files: Record<string, string>;
  /**
   * 입력 단계 판정 규칙의 판 (소속·시간·연결 검증)
   */
  input_stage_edition: string;
  /**
   * members가 가리키는 행 내용 + rule_files를 정규화(JSON, 키 정렬)한 SHA-256
   */
  content_sha256: string;
  onto_version: string;
  vocabulary_version: string;
  label_dictionary_version: string;
  /**
   * contracts 패키지 semver
   */
  schema_version: string;
  extractor_versions: string[];
  model_versions: ModelVersion[];
  engine_version: string;
  rule_schema_versions: string[];
  capability_table_hash: string;
  explain_template_hash: string;
  /**
   * 이전 릴리스와 같은 입력 비교 결과. 첫 릴리스는 비교 대상이 없어 생략
   */
  shadow_compare_report_id?: string;
  /**
   * K1~K16 위반 0건 보고
   */
  constraint_report_id: string;
  superseded_by?: string;
  withdrawn_at?: string;
  withdrawal_reason?: string;
}

/**
 * 입력 단계 판정. 규칙 근거와 분리한다 (02 §2.4)
 */
export interface InputJudgement {
  input_name: string;
  value: Tri;
  /**
   * 판정 주체. 02 §2.4에 값 집합이 없다. 어휘 축 승격 대기
   */
  judged_by: string;
  evidence_assertion_ids: string[];
}

/**
 * 입력 단계가 계산을 막은 이유 (02 §1.7 resolve_chain Blocked)
 */
export interface BlockedBy {
  /**
   * no_uses_edition, multiple_candidates, scope_unknown, application_scope_unverified, applies_from_other_edition_unmodeled, competing_editions, link_unapproved, edition_identity_unconfirmed, cov_not_in_edition, no_rule. 어휘 축 승격 대기
   */
  reason: string;
  held_conclusions: string[];
}

/**
 * 설명 문장. 금액은 금액마다 출처를 선언한다
 */
export interface Explain {
  template_id: string;
  text: string;
  amounts: Amount[];
}

/**
 * 시나리오 결과: EvaluationResult + 입력 단계 판정 + 설명 + 막힘 (02_구현계약 §2.1·§2.4)
 */
export interface ScenarioResult {
  /**
   * 모든 응답은 release_id를 echo한다
   */
  release_id: string;
  cov_id: string;
  /**
   * 엔진 결과. 막혔으면(blocked_by) 엔진 호출 0건이라 없다
   */
  evaluation?: EvaluationResult;
  judgements: InputJudgement[];
  blocked_by: BlockedBy[];
  remaining_gaps: string[];
  explain?: Explain;
  display_status: DisplayStatus;
  result_state: ResultState;
  dependency?: DependencyInfo;
}
